export const COLLISION_SHAPE_NAMES = ['auto', 'none', 'box', 'compound', 'convex', 'convex_decomposition', 'trimesh'] as const;
export const COLLISION_USAGE_NAMES = ['ground', 'wall', 'structure', 'rock', 'prop', 'character', 'vehicle', 'vegetation', 'effect', 'decal'] as const;
/** Largest side (metres) above which a fixed decor without collision is reported (same threshold as the server's level check). */
export const MASSIVE_DECOR = 1.5;
const home = () => process.env.GRIP_FORGE_HOME || join(homedir(), '.grip-forge');

export interface CollisionDescriptionLike { method: string; choice?: { method?: string; score?: number; reason?: string; auto?: boolean }; parts: unknown[]; bounds?: { min: number[]; max: number[] }; usage?: string; [k: string]: unknown }
export interface CollisionWarning { slot?: string; item?: string; size: number; method: string; reason: string; message: string }

export interface CollisionBuilt {
  input: string;
  kind: string;
  key: string;
  options: Record<string, unknown>;
  description: CollisionDescriptionLike;
  report?: Record<string, unknown>;
  file?: string;
  ms?: number;
  /** method / score / reason of the choice: what the tool chose and why. */
  method: string;
  score: number | null;
  reason: string | null;
  parts: number;
  warning?: CollisionWarning;
}

/** The method, score and reason of a description. */
export function choiceOfDescription(d: CollisionDescriptionLike | null): { method: string; score: number | null; reason: string | null; parts: number } {
  return d ? { method: d.method, score: typeof d.choice?.score === 'number' ? d.choice.score : null, reason: d.choice?.reason ?? null, parts: d.parts.length } : { method: 'missing', score: null, reason: 'not made yet', parts: 0 };
}

/** The level check for one model made here: a fixed decor of 1.5 m or more that collides with nothing. */
export function collisionWarningOf(d: CollisionDescriptionLike, label: string): CollisionWarning | undefined {
  const usage = String(d.usage ?? 'prop'), b = d.bounds;
  if (d.method !== 'none' || ['character', 'vehicle', 'effect', 'decal'].includes(usage) || !b) return undefined;
  const size = Math.max(...b.max.map((v, i) => v - (b.min[i] ?? 0)));
  if (!(size >= MASSIVE_DECOR)) return undefined;
  const reason = d.choice?.reason ?? 'the tool chose none';
  return { size: Math.round(size * 100) / 100, method: 'none', reason, message: `${label}: ${size.toFixed(1)} m of ${usage} without collision (${reason}) — a character walks through it. Fix: kits.collision.shape in the passport (not by hand in the game).` };
}

export interface CollisionFileOptions {
  kit: Kit;
  /** Folder of `collision.json` (default `<folder of the file>/gripforge-collision/<name>/`). */
  out?: string;
  passport?: string | Record<string, unknown>;
  override?: Record<string, unknown>;
  kind?: string;
  /** The options the server resolved (they replace passport and override). */
  options?: Record<string, unknown>;
  meta?: Record<string, unknown>;
  name?: string;
  signal?: AbortSignal;
}

/** The collision of one `.glb`. */
export async function collisionFile(file: string, o: CollisionFileOptions): Promise<CollisionBuilt> {
  const input = resolve(file);
  if (!existsSync(input)) throw Error(`${input} does not exist.`);
  let passport = o.passport;
  if (passport === undefined) { const side = join(dirname(input), `${basename(input, extname(input))}.gfmesh.json`); if (existsSync(side)) passport = side; }
  const out = resolve(o.out ?? join(dirname(input), 'gripforge-collision', basename(input, extname(input))));
  const r = await runKit<Omit<CollisionBuilt, 'method' | 'score' | 'reason' | 'parts'>>(o.kit, { op: 'collision', input, out, passport, override: o.override, kind: o.kind, options: o.options, meta: o.meta, name: o.name ?? basename(input, extname(input)), bin: o.kit.collisionBin ?? undefined }, o.signal);
  const built: CollisionBuilt = { ...r, ...choiceOfDescription(r.description) };
  const warning = collisionWarningOf(r.description, basename(input));
  if (warning) built.warning = warning;
  return built;
}

