const rowReport = (r: PlanRow, status: CollisionRowReport['status'], extra: Partial<CollisionRowReport> = {}): CollisionRowReport => ({ slot: r.slot, item: r.item, name: r.name, key: r.key, method: r.method, score: r.score, reason: r.reason, parts: r.parts, status, ...extra });

/**
 * The collision a game's bound models still need, made here. The server says what each model needs — the effective
 * `kits.collision` (global passport, then the game's own `asset_passports`), the options and the key — and this makes the
 * missing ones with the kit, checks each carries the key asked, sends it back, then reads the level check again.
 */
export async function collisionGame(transport: LodTransport, project: string, o: CollisionGameOptions): Promise<CollisionGameReport> {
  const log = o.log ?? (() => undefined);
  const path = `/api/v1/gamekit-projects/${encodeURIComponent(project)}/collision`;
  const mode = o.check ? 'check' : o.server ? 'server' : o.dryRun ? 'dry-run' : 'local';
  const adviceBody = o.advice || o.force ? { advice: true, ...(o.force ? { force: true } : {}) } : {};
  let plan = await transport.json<Plan>(path, o.server && !o.check ? { method: 'POST', body: adviceBody } : {});
  const report: CollisionGameReport = { project, mode, models: [], warnings: [], made: 0, current: 0, adopted: 0, skipped: 0 };
  if (mode === 'local') {
    if (!o.kit) throw Error('The collision kit is required to make collisions here.');
    const work = resolve(o.out ?? join(process.env.GRIPFORGE_COLLISION_WORK ?? join(home(), 'cache', 'collision-work'), project));
    const done = new Map<string, CollisionRowReport>();
    for (const row of plan.models) {
      if (row.made) { report.current++; done.set(row.slot, rowReport(row, 'current', { note: row.method === 'custom' ? 'parts written by hand' : 'already on the server' })); continue; }
      try {
        const dir = join(work, row.item);
        await mkdir(dir, { recursive: true });
        const source = join(dir, 'source.glb');
        log(`${row.name || row.item}: downloading ${row.item}`);
        await writeFile(source, await transport.bytes(`/api/v1/library/${row.item}/file`));
        const built = await collisionFile(source, { kit: o.kit, out: join(dir, row.key), options: row.options, signal: o.signal });
        const choice = choiceOfDescription(built.description);
        const base = { ...choice, file: built.file };
        if (built.key !== row.key) { report.skipped++; done.set(row.slot, rowReport(row, 'refused', { ...base, pushed: 'refused', note: `key differs from the server's (${row.key})` })); continue; }
        report.made++;
        if (o.push !== false) {
          try {
            await transport.json(`/api/v1/library/${row.item}/collision`, { method: 'PUT', body: { key: built.key, description: built.description, section: row.section } });
            report.adopted++; done.set(row.slot, rowReport(row, 'made', { ...base, pushed: 'adopted' }));
          } catch (e) { done.set(row.slot, rowReport(row, 'made', { ...base, pushed: 'refused', note: e instanceof Error ? e.message : String(e) })); }
        } else done.set(row.slot, rowReport(row, 'made', { ...base, pushed: 'kept' }));
      } catch (e) {
        const note = e instanceof Error ? e.message : String(e);
        log(`${row.name || row.item}: left to the service (${note})`);
        report.skipped++; done.set(row.slot, rowReport(row, 'skipped', { note }));
      }
    }
    // The advice (on request), then the level check on what the server now holds.
    if (o.advice || o.force) plan = await transport.json<Plan>(path, { method: 'POST', body: adviceBody });
    else if (report.adopted) plan = await transport.json<Plan>(path);
    report.models = plan.models.map((r) => done.get(r.slot) && !r.made ? done.get(r.slot)! : done.get(r.slot) && r.made && done.get(r.slot)!.status === 'made' ? { ...done.get(r.slot)!, method: r.method, score: r.score, reason: r.reason, parts: r.parts } : rowReport(r, r.made ? 'current' : 'missing'));
  } else {
    for (const r of plan.models) {
      if (r.made) report.current++;
      report.models.push(rowReport(r, r.made ? (mode === 'server' && !r.error ? 'made' : 'current') : 'missing', r.error ? { note: r.error } : {}));
      if (r.made && mode === 'server') report.made++;
    }
  }
  report.warnings = plan.warnings ?? [];
  return report;
}

const score = (s: number | null) => (s === null ? '' : ` ${s.toFixed(2)}`);

/** Plain-text lines for one model made from a file: the CHOICE and its reason. */
export function collisionLines(b: CollisionBuilt): string[] {
  const lines = [`${b.input} (${b.kind}) — ${b.method}${score(b.score)}, ${b.parts} part${b.parts === 1 ? '' : 's'}${b.file ? ` → ${b.file}` : ''}`];
  if (b.reason) lines.push(`  why: ${b.reason}`);
  if (b.warning) lines.push(`  warning: ${b.warning.message}`);
  return lines;
}

/** Plain-text lines for a game: per model, the method, the score and the reason. */
export function collisionGameLines(r: CollisionGameReport): string[] {
  const lines = [`Collision · ${r.project} — ${r.made} made, ${r.current} already made${r.adopted ? `, ${r.adopted} kept by the server` : ''}${r.skipped ? `, ${r.skipped} left to the service` : ''}`];
  for (const m of r.models) {
    lines.push(`  ${m.slot.padEnd(28)} ${m.method.padEnd(20)}${score(m.score).padEnd(6)} ${m.status}${m.pushed ? ` (${m.pushed})` : ''}${m.note ? ` ${m.note}` : ''}`.trimEnd());
    if (m.reason) lines.push(`    why: ${m.reason}`);
  }
  for (const w of r.warnings) lines.push(`  warning: ${w.message}`);
  return lines;
}
